parameters.textBody:
=✅ تم تأكيد حجزك بنجاح

الخدمة: {{ $('Get Pending Booking').item.json.service }}
الاسم: {{ $('Get Pending Booking').item.json.customerName }}
التاريخ: {{ $('Get Pending Booking').item.json.date }}
الوقت: {{ $('Get Pending Booking').item.json.time }}

ننتظرك في الموعد 🌷

=عذرًا، العيادة مغلقة بتاريخ {{ $('Extract Booking Details').first().json.output.date }}.

السبب: {{ $('Get Clinic Holiday').first().json.reason }}

يرجى اختيار تاريخ آخر.

={{
(() => {
  const data = $('Extract Booking Details').first().json.output;
  const missing = [];

  if (!data.service) missing.push('اسم الخدمة');
  if (!data.date) missing.push('التاريخ المطلوب');
  if (!data.time) missing.push('الوقت مع تحديد صباحًا أو مساءً، مثل: 9 صباحًا أو 9 مساءً');
  if (!data.customerName) missing.push('اسمك');

  return `حتى أساعدك في الحجز، أرسل المعلومات الناقصة:\n\n${missing.map(field => `• ${field}`).join('\n')}`;
})()
}}

